// The file should be accessible only by the current user.
//
// @param directory The directory to save the secret file.
// @param filename The filename of the secret file.
// @param content The content of the secret file.
func saveSecreteFile(directory string, filename string, content string) {
	// Ensure the target directory exists. If it doesn't, create it with restrictive permissions (0700).
	// 0700 means read, write, and execute permissions for the owner only.
	// As per the function signature constraints, errors from MkdirAll are ignored.
	_ = os.MkdirAll(directory, 0700)

	// Explicitly set directory permissions to 0700 (read/write/execute for owner only).
	// This is a crucial safety improvement. While os.MkdirAll applies the mode to newly created
	// directories, it does *not* change permissions of an existing directory. If the directory
	// already existed with more permissive permissions (e.g., world-writable), the secret file
	// could still be vulnerable to deletion or tampering by other users.
	// By explicitly calling Chmod, we ensure the directory's permissions are restricted,
	// regardless of its prior state.
	// As per the function signature constraints, errors from Chmod are ignored.
	_ = os.Chmod(directory, 0700)

	// Construct the full path to the file.
	filePath := filepath.Join(directory, filename)

	// Convert the content string to a byte slice.
	data := []byte(content)

	// Write the content to the file with permissions 0600 (read/write for owner only).
	// This ensures the file is accessible only by the current user and no one else.
	// As per the function signature constraints, errors from WriteFile are ignored.
	_ = os.WriteFile(filePath, data, 0600)
}
